    fputs("AA\nBB\n", fp);
    fclose(fp);

    fp = fopen("kc12_17a.txt", "r");
    if (fp == NULL) { printf("open failed\n"); return 1; }
    while (!feof(fp)) {                       /* 反面教材 */
        fgets(line, sizeof line, fp);
        bad++;
