    printf("bad  loop count=%d\n", bad);

    fp = fopen("kc12_17a.txt", "r");
    if (fp == NULL) { printf("open failed\n"); return 1; }
    while (fgets(line, sizeof line, fp) != NULL) good++;
    fclose(fp);
    remove("kc12_17a.txt");
    printf("good loop count=%d\n", good);
    return 0;
}

