    fp = fopen("kc12_25a.bin", "rb");
    if (fp == NULL) return 1;
    while ((ci = fgetc(fp)) != EOF) n_int++;
    fclose(fp);
    printf("int  counter=%d\n", n_int);

    fp = fopen("kc12_25a.bin", "rb");
    if (fp == NULL) return 1;
    for (;;) {
        ci = fgetc(fp);
        if (ci == EOF) break;
        cc = (char)ci;
        if (cc == (char)EOF) break;   /* 0xFF 变成 -1，与 EOF 无法区分 */
        n_char++;
        if (n_char > 100) break;
    }
    fclose(fp);
    printf("char counter=%d\n", n_char);

    remove("kc12_25a.bin");
    return 0;
}

#include <stdio.h>

static void dump(const char *tag, const char *name)
{
    FILE *r = fopen(name, "r");
    char buf[128];
    size_t n;
    if (r == NULL) { printf("%s [missing]\n", tag); return; }
    n = fread(buf, 1, sizeof buf - 1, r);
    buf[n] = '\0';
    printf("%s [%s]\n", tag, buf);
    fclose(r);
}

int main(void)
{
    FILE *fp;

    remove("kc12_25b.txt");

    fp = fopen("kc12_25b.txt", "w");
    if (fp == NULL) return 1;
    fputs("first ", fp);
    fclose(fp);

    fp = fopen("kc12_25b.txt", "w");   /* 错：想追加却用了 w */
    if (fp == NULL) return 1;
    fputs("second", fp);
    fclose(fp);
    dump("after w:", "kc12_25b.txt");

    fp = fopen("kc12_25b.txt", "a");   /* 对：追加 */
    if (fp == NULL) return 1;
    fputs(" third", fp);
    fclose(fp);
    dump("after a:", "kc12_25b.txt");

    remove("kc12_25b.txt");
    return 0;
}
